    "c4_l2_3": "Requisitos de la Ley de Accesibilidad de Canadá (ACA) para organizaciones de regulación federal",
    "c5_h3": "Seguridad de Comando y Control (C2) en Robótica Humanoide",
    "c5_l1": "Endurecimiento de canales C2 de teleoperación, cifrado e aislamiento de flujos de baja latencia",
    "c5_l2": "Seguridad de nodos en Sistema Operativo para Robots 2 (ROS2), integridad de buses CAN / EtherCAT e interbloqueos de Paro de Emergencia (E-stop)",
    "c5_l3": "Protección contra falsificación de sensores dirigida a arreglos LiDAR, cámaras y sensores inerciales",
    "c6_h3": "Garantía de Modelos y Tuberías de Inteligencia Artificial (IA)",
    "c6_tag": "(Calificación a la Lista de Fuentes de IA Federal en preparación, ITQ WS4286933967)",
    "c6_l1": "Seguridad en tuberías de datos de entrenamiento, auditorías de envenenamiento de datos y defensas contra extracción de modelos",
    "c6_l2": "Seguridad en límites de API de inferencia, integridad de indicaciones y validación de instrucciones de agentes",
    "c6_l3": "Revisión independiente de Evaluaciones de Impacto Algorítmico conforme a la Directiva sobre Toma de Decisiones Automatizada del Consejo del Tesoro",
    "cusma_tag": "América del Norte",
